"""Row 373 (Pillow 13): a malformed image is a 400 "not a readable image", never a 500.

Pillow 13 raises KeyError while iterating the EXIF of a TIFF whose tag table is cut short.
The EXIF read used to sit outside the guarded block, so that reached the catch-all handler.
"""

from __future__ import annotations

import base64

import pytest

from src.verification.metadata import ImageError, extract_image_metadata

# 1018 bytes: a TIFF whose tag table makes Pillow 13 raise KeyError: 262 in getexif().items()
_BAD_TIFF = base64.b64decode(
    ""
)


def test_truncated_tiff_tags_are_not_a_readable_image():
    with pytest.raises(ImageError) as info:
        extract_image_metadata(_BAD_TIFF)
    assert str(info.value).startswith("not a readable image")


def test_message_names_no_python_object_address():
    with pytest.raises(ImageError) as info:
        extract_image_metadata(b"\x00" * 64)
    assert " at 0x" not in str(info.value)


def test_api_answers_400_not_500():
    from fastapi.testclient import TestClient

    from src.api.main import app

    client = TestClient(app, raise_server_exceptions=False)
    r = client.post(
        "/api/verify/image-metadata",
        files={"file": ("bad.tif", _BAD_TIFF, "image/tiff")},
    )
    assert r.status_code == 400, r.text
    assert "not a readable image" in r.text
